def solve(nums, target):
    ending = nums[0]
    best = ending
    for i in range(1, len(nums)):
        extended = ending + nums[i]
        if extended > nums[i]:
            ending = extended
        else:
            ending = nums[i]
        if ending > best:
            best = ending
    return best
